def test_book_native_side_receipt_requires_current_neg_risk_state_shape():
    state = (
        "family",
        "20C",
        "condition",
        "YES",
        "token",
        "EXECUTABLE",
        "book-hash",
        "event",
        "gamma",
        "False",
    )
    candidate_index = ((
        "candidate",
        "family",
        "20C",
        "condition",
        "YES",
        "token",
    ),)
    receipt = global_batch_runtime._book_native_side_receipt(
        asset_states=(state,),
        probability_keys=("family",),
        buy_candidate_index=candidate_index,
        excluded_by_family={},
    )
    payload_json = zlib.decompress(
        base64.b64decode(receipt["book_native_side_states_zlib_b64"])
    )
    payload = json.loads(payload_json)
    assert payload["fields"][-1] == "neg_risk"
    assert payload["rows"] == [list(state)]
    assert hashlib.sha256(payload_json).hexdigest() == receipt[
        "book_native_side_states_sha256"
    ]

    with pytest.raises(
        ValueError,
        match="GLOBAL_AUCTION_RECEIPT_BOOK_SIDE_STATE_INVALID",
    ):
        global_batch_runtime._book_native_side_receipt(
            asset_states=(state[:-1],),
            probability_keys=("family",),
            buy_candidate_index=candidate_index,
            excluded_by_family={},
        )

    with pytest.raises(
        ValueError,
        match="GLOBAL_AUCTION_RECEIPT_BOOK_SIDE_STATE_INVALID",
    ):
        global_batch_runtime._book_native_side_receipt(
            asset_states=((*state[:-1], "0"),),
            probability_keys=("family",),
            buy_candidate_index=candidate_index,
            excluded_by_family={},
        )

    with pytest.raises(
        ValueError,
        match="GLOBAL_AUCTION_RECEIPT_BOOK_SIDE_STATE_INVALID",
    ):
        global_batch_runtime._book_native_side_receipt(
            asset_states=((*state[:-1], False),),
            probability_keys=("family",),
            buy_candidate_index=candidate_index,
            excluded_by_family={},
        )

    delta = global_batch_runtime._book_native_side_delta_receipt(
        base_rows=(state,),
        current_rows=((*state[:-1], "True"),),
    )
    delta_payload = json.loads(
        zlib.decompress(base64.b64decode(delta["book_native_side_delta_zlib_b64"]))
    )
    assert delta_payload["fields"][-1] == "neg_risk"
    assert delta_payload["upsert_rows"] == [list((*state[:-1], "True"))]


def test_compact_buy_rejection_group_requires_complete_economic_frontier():
    def row(candidate_id: str, growth: float, delta: float) -> dict[str, object]:
        return {
            "candidate_id": candidate_id,
            "family_key": f"family-{candidate_id}",
            "bin_id": "32C",
            "condition_id": f"condition-{candidate_id}",
            "token_id": f"token-{candidate_id}",
            "buy_rejection_economics": {
                "probe_robust_log_growth_per_hour": growth,
                "probe_robust_delta_log_wealth": delta,
                "probe_capital_efficiency": delta / 5,
                "probe_cost_usd": "5",
            },
        }

    complete = global_batch_runtime._compact_buy_rejection_group(
        action="BUY",
        side="YES",
        reason="NON_POSITIVE_ROBUST_OBJECTIVE",
        rows=(
            row("worse", -0.002, -0.02),
            row("nearest-cash", -0.001, -0.03),
        ),
        buy_candidate_positions={"worse": 0, "nearest-cash": 1},
    )

    assert complete["frontier_complete"] is True
    assert complete["economics_candidate_count"] == 2
    assert complete["frontier"]["candidate_index"] == 1
    assert complete["candidate_indexes"] == [0, 1]

    incomplete = global_batch_runtime._compact_buy_rejection_group(
        action="BUY",
        side="NO",
        reason="DEPTH_INFEASIBLE",
        rows=(row("measured", -0.001, -0.01), {"candidate_id": "missing"}),
        buy_candidate_positions={"measured": 0, "missing": 1},
    )

    assert incomplete["frontier_complete"] is False
    assert incomplete["economics_candidate_count"] == 1
    assert incomplete["frontier"] is None


