def test_candidate_semantic_delta_does_not_rewrite_stable_action_slots():
    def payload(epoch: str) -> dict[str, object]:
        detailed = [
            {
                "candidate_id": hashlib.sha256(
                    f"{epoch}:{index}".encode()
                ).hexdigest(),
                "action": "SELL",
                "family_key": f"family-{index}",
                "bin_id": f"bin-{index}",
                "condition_id": f"condition-{index}",
                "side": "YES",
                "token_id": f"token-{index}",
                "position_id": f"position-{index}",
                "status": "REJECTED",
                "stable_probability_evidence": {
                    f"field-{field}": hashlib.sha256(
                        f"stable:{index}:{field}".encode()
                    ).hexdigest()
                    for field in range(8)
                },
                "sell_action_authority_identity": hashlib.sha256(
                    f"authority:{epoch}:{index}".encode()
                ).hexdigest(),
                "sell_point_counterfactual": {
                    "book_identity": hashlib.sha256(
                        f"book:{epoch}:{index}".encode()
                    ).hexdigest(),
                    "status": "NON_POSITIVE",
                },
            }
            for index in range(48)
        ]
        detailed.sort(key=global_batch_runtime._candidate_semantic_key)
        return {
            "rejected_groups": [],
            "detailed": detailed,
            "buy_condition_side_masks": [],
            "buy_candidate_index_fields": [],
            "buy_candidate_index": [],
        }

    base = payload("base")
    current = payload("current")
    expected_sha256 = hashlib.sha256(
        global_batch_runtime._canonical_json_bytes(current)
    ).hexdigest()

    semantic = global_batch_runtime._candidate_evaluations_delta_receipt(
        base=base,
        current=current,
        expected_sha256=expected_sha256,
    )
    legacy = global_batch_runtime._json_object_delta_receipt(
        prefix="candidate_evaluations",
        base=base,
        current=current,
        expected_sha256=expected_sha256,
    )
    semantic_raw = zlib.decompress(
        base64.b64decode(
            semantic["candidate_evaluations_delta_zlib_b64"]
        )
    )
    reconstructed = global_batch_runtime._apply_candidate_evaluations_delta(
        base,
        json.loads(semantic_raw),
    )

    assert reconstructed == current
    assert semantic["candidate_evaluations_delta_encoding"] == (
        "zlib+base64+semantic-keyed-canonical-json-delta-v3"
    )
    assert len(semantic["candidate_evaluations_delta_zlib_b64"]) < len(
        legacy["candidate_evaluations_delta_zlib_b64"]
    )
    assert semantic["candidate_evaluations_delta_detailed_patch_count"] == 48


def test_candidate_delta_keys_high_cardinality_indexes_instead_of_rewriting():
    def candidate_row(index: int, candidate_id: str) -> list[str]:
        return [
            candidate_id,
            f"family-{index // 20}",
            f"bin-{index}",
            f"condition-{index // 2}",
            "YES" if index % 2 == 0 else "NO",
            f"token-{index}",
            "TAKER_LIMIT" if index % 3 else "MAKER_REST",
        ]

    count = 1_024
    base_index = [
        candidate_row(
            index,
            hashlib.sha256(f"candidate:{index}".encode()).hexdigest(),
        )
        for index in range(count)
    ]
    current_index = [list(row) for row in base_index]
    current_index[617][0] = hashlib.sha256(b"candidate:617:current").hexdigest()
    base_masks = sorted(
        [
            (f"condition-{index}", 3)
            for index in range(count // 2)
        ]
    )
    current_masks = [
        [condition_id, mask]
        for condition_id, mask in base_masks
    ]
    current_masks[211][1] = 1
    current_masks = sorted(
        (str(condition_id), int(mask))
        for condition_id, mask in current_masks
    )
    base = {
        "rejected_groups": [],
        "detailed": [],
        "buy_condition_side_masks": base_masks,
        "buy_candidate_index_fields": [
            "candidate_id",
            "family_key",
            "bin_id",
            "condition_id",
            "side",
            "token_id",
            "execution_mode",
        ],
        "buy_candidate_index": sorted(base_index),
    }
    current = {
        **base,
        "buy_condition_side_masks": current_masks,
        "buy_candidate_index": sorted(current_index),
    }
    expected_sha256 = hashlib.sha256(
        global_batch_runtime._canonical_json_bytes(current)
    ).hexdigest()

    receipt = global_batch_runtime._candidate_evaluations_delta_receipt(
        base=base,
        current=current,
        expected_sha256=expected_sha256,
    )
    delta_raw = zlib.decompress(
        base64.b64decode(receipt["candidate_evaluations_delta_zlib_b64"])
    )
    delta = json.loads(delta_raw)

    assert receipt["candidate_evaluations_delta_buy_index_patch_count"] == 1
    assert (
        receipt["candidate_evaluations_delta_condition_mask_patch_count"] == 1
    )
    assert global_batch_runtime._apply_candidate_evaluations_delta(
        base,
        delta,
    ) == current
    full_b64 = base64.b64encode(
        zlib.compress(
            global_batch_runtime._canonical_json_bytes(current),
            level=9,
        )
    )
    assert len(receipt["candidate_evaluations_delta_zlib_b64"]) * 2 < len(
        full_b64
    )

    duplicate_patch = json.loads(delta_raw)
    duplicate_patch["buy_candidate_index"]["patches"].append(
        duplicate_patch["buy_candidate_index"]["patches"][0]
    )
    with pytest.raises(
        ValueError,
        match="GLOBAL_AUCTION_RECEIPT_BUY_INDEX_DELTA_INVALID",
    ):
        global_batch_runtime._apply_candidate_evaluations_delta(
            base,
            duplicate_patch,
        )

    duplicate_mask_patch = json.loads(delta_raw)
    duplicate_mask_patch["buy_condition_side_masks"]["patches"].append(
        duplicate_mask_patch["buy_condition_side_masks"]["patches"][0]
    )
    with pytest.raises(
        ValueError,
        match="GLOBAL_AUCTION_RECEIPT_CONDITION_MASK_DELTA_INVALID",
    ):
        global_batch_runtime._apply_candidate_evaluations_delta(
            base,
            duplicate_mask_patch,
        )

    string_removed_masks = json.loads(delta_raw)
    string_removed_masks["buy_condition_side_masks"]["removed_keys"] = "abc"
    with pytest.raises(
        ValueError,
        match="GLOBAL_AUCTION_RECEIPT_CONDITION_MASK_DELTA_INVALID",
    ):
        global_batch_runtime._apply_candidate_evaluations_delta(
            base,
            string_removed_masks,
        )

    string_removed_candidates = json.loads(delta_raw)
    string_removed_candidates["buy_candidate_index"]["removed_keys"] = "abc"
    with pytest.raises(
        ValueError,
        match="GLOBAL_AUCTION_RECEIPT_BUY_INDEX_DELTA_INVALID",
    ):
        global_batch_runtime._apply_candidate_evaluations_delta(
            base,
            string_removed_candidates,
        )


def test_candidate_delta_packs_full_high_cardinality_id_rotation():
    count = 1_024

    def candidate_index(epoch: str) -> list[list[str]]:
        return sorted(
            [
                hashlib.sha256(f"{epoch}:{index}".encode()).hexdigest(),
                f"family-{index // 20}",
                f"bin-{index}",
                f"condition-{index // 2}",
                "YES" if index % 2 == 0 else "NO",
                f"token-{index}",
                "TAKER_LIMIT" if index % 3 else "MAKER_REST",
            ]
            for index in range(count)
        )

    base = {
        "rejected_groups": [],
        "detailed": [],
        "buy_condition_side_masks": [],
        "buy_candidate_index_fields": [
            "candidate_id",
            "family_key",
            "bin_id",
            "condition_id",
            "side",
            "token_id",
            "execution_mode",
        ],
        "buy_candidate_index": candidate_index("base"),
    }
    current = {**base, "buy_candidate_index": candidate_index("current")}
    receipt = global_batch_runtime._candidate_evaluations_delta_receipt(
        base=base,
        current=current,
        expected_sha256=hashlib.sha256(
            global_batch_runtime._canonical_json_bytes(current)
        ).hexdigest(),
    )
    delta_raw = zlib.decompress(
        base64.b64decode(receipt["candidate_evaluations_delta_zlib_b64"])
    )
    delta = json.loads(delta_raw)

    assert receipt["candidate_evaluations_delta_buy_index_patch_count"] == count
    assert receipt["candidate_evaluations_delta_buy_index_packed"] is True
    assert receipt["candidate_evaluations_delta_encoding"] == (
        "zlib+base64+semantic-keyed-canonical-json-delta-v4"
    )
    assert delta["buy_candidate_index"]["patches"] == []
    assert delta["buy_candidate_index"]["candidate_ids_count"] == count
    assert global_batch_runtime._apply_candidate_evaluations_delta(
        base,
        delta,
    ) == current

    unpacked = json.loads(delta_raw)
    unpacked["buy_candidate_index"] = {
        "key_fields": list(global_batch_runtime._BUY_CANDIDATE_INDEX_KEY_FIELDS),
        "removed_keys": [],
        "patches": [
            {
                "key": row[1:],
                "candidate_id": row[0],
            }
            for row in current["buy_candidate_index"]
        ],
    }
    unpacked_b64 = base64.b64encode(
        zlib.compress(
            global_batch_runtime._canonical_json_bytes(unpacked),
            level=9,
        )
    )
    assert len(receipt["candidate_evaluations_delta_zlib_b64"]) * 4 < len(
        unpacked_b64
    ) * 3

    changed_keys_index = candidate_index("changed-keys")[:-1]
    changed_keys_index.append(
        [
            hashlib.sha256(b"changed-keys:new").hexdigest(),
            "family-new",
            "bin-new",
            "condition-new",
            "YES",
            "token-new",
            "TAKER_LIMIT",
        ]
    )
    changed_keys_current = {
        **base,
        "buy_candidate_index": sorted(changed_keys_index),
    }
    changed_keys_receipt = (
        global_batch_runtime._candidate_evaluations_delta_receipt(
            base=base,
            current=changed_keys_current,
            expected_sha256=hashlib.sha256(
                global_batch_runtime._canonical_json_bytes(
                    changed_keys_current
                )
            ).hexdigest(),
        )
    )
    changed_keys_delta = json.loads(
        zlib.decompress(
            base64.b64decode(
                changed_keys_receipt[
                    "candidate_evaluations_delta_zlib_b64"
                ]
            )
        )
    )
    assert changed_keys_receipt[
        "candidate_evaluations_delta_buy_index_packed"
    ] is True
    assert len(changed_keys_delta["buy_candidate_index"]["removed_keys"]) == 1
    assert len(changed_keys_delta["buy_candidate_index"]["patches"]) == 1
    assert global_batch_runtime._apply_candidate_evaluations_delta(
        base,
        changed_keys_delta,
    ) == changed_keys_current


def test_candidate_delta_reader_replays_pre_execution_mode_v3_index():
    fields = list(global_batch_runtime._LEGACY_BUY_CANDIDATE_INDEX_KEY_FIELDS)
    base = {
        "rejected_groups": [],
        "detailed": [],
        "buy_candidate_index_fields": ["candidate_id", *fields],
        "buy_candidate_index": [
            ["candidate-old", "family", "bin", "condition", "YES", "token"]
        ],
        "buy_condition_side_masks": [("condition", 1)],
    }
    current = {
        **base,
        "buy_candidate_index": [
            ["candidate-new", "family", "bin", "condition", "YES", "token"]
        ],
    }
    delta = {
        "top_level": {"removed_keys": [], "replacements": {}},
        "detailed": {
            "semantic_key_fields": list(
                global_batch_runtime._LEGACY_CANDIDATE_SEMANTIC_KEY_FIELDS
            ),
            "removed_keys": [],
            "patches": [],
        },
        "buy_candidate_index": {
            "key_fields": fields,
            "removed_keys": [],
            "patches": [
                {
                    "key": ["family", "bin", "condition", "YES", "token"],
                    "candidate_id": "candidate-new",
                }
            ],
        },
        "buy_condition_side_masks": {
            "removed_keys": [],
            "patches": [],
        },
    }

    assert (
        global_batch_runtime._apply_candidate_evaluations_delta(base, delta)
        == current
    )


def test_durable_global_holding_coverage_requires_position_q_and_fresh_book(
    monkeypatch,
):
    monkeypatch.setattr(
        global_batch_runtime,
        "_GLOBAL_HOLDING_COVERAGE_BY_POSITION",
        {},
    )
    monkeypatch.setattr(
        global_batch_runtime,
        "_GLOBAL_HOLDING_COVERAGE_WEALTH_IDENTITY",
        None,
    )
    at = _dt.datetime(2026, 7, 14, 1, 0, tzinfo=_dt.timezone.utc)
    obligation = global_batch_runtime._CurrentHeldObligation(
        position_id="position-1",
        family_key="family-1",
        bin_label="20C",
        condition_id="condition-1",
        side="YES",
        token_id="token-1",
        held_shares=Decimal("10"),
    )
    probability = SimpleNamespace(
        witness_identity="q-1",
        probability_content_identity="q-content-1",
        bindings=(
            SimpleNamespace(
                bin_id="20C",
                condition_id="condition-1",
                yes_token_id="token-1",
                no_token_id="token-no-1",
            ),
        )
    )
    evaluated = GlobalHoldingAuctionCoverage(
        position_id="position-1",
        family_key="family-1",
        bin_id="20C",
        bin_label="20C",
        condition_id="condition-1",
        side="YES",
        token_id="token-1",
        held_shares=Decimal("10"),
        ledger_snapshot_id="ledger-1",
        probability_witness_identity="q-1",
        probability_content_identity="q-content-1",
        wealth_economic_identity="wealth-1",
        selection_epoch_identity="epoch-1",
        book_epoch_identity="book-1",
        selection_cut_at_utc=at,
        decision_at_utc=at + _dt.timedelta(seconds=1),
        book_deadline_at_utc=at + _dt.timedelta(seconds=30),
        status="EVALUATED",
        candidate_id="sell-1",
        sell_book_witness_identity="sell-book-1",
        book_state="EXECUTABLE",
    )
    dual_mode = replace(
        evaluated,
        candidate_id="sell-taker",
        candidate_ids=("sell-taker", "sell-maker"),
    )
    assert global_batch_runtime._holding_coverage_owns_sell_candidate(
        dual_mode,
        candidate_id="sell-maker",
        token_id="token-1",
    )
    assert not global_batch_runtime._holding_coverage_owns_sell_candidate(
        dual_mode,
        candidate_id="sell-maker",
        token_id="other-token",
    )
    global_batch_runtime._publish_global_holding_coverage(
        (evaluated,),
        expected_obligations=(obligation,),
        probability_witnesses={"family-1": probability},
        decision_log_id=42,
    )

    current = dict(
        position_id="position-1",
        probability_content_identity="q-content-1",
        checked_at_utc=at + _dt.timedelta(seconds=2),
        family_key="family-1",
        bin_label="20C",
        condition_id="condition-1",
        side="YES",
        token_id="token-1",
        held_shares=Decimal("10"),
        current_ledger_snapshot_id="ledger-1",
        current_wealth_economic_identity="wealth-1",
        current_probability_content_identity_resolver=lambda _row: "q-content-1",
        current_holding_witness_resolver=lambda _row: (
            global_batch_runtime._CurrentHoldingWitness(
                ledger_snapshot_id="ledger-1",
                wealth_economic_identity="wealth-1",
                held_shares=Decimal("10"),
            )
        ),
        current_time_provider=lambda: at + _dt.timedelta(seconds=2),
    )
    covered = global_batch_runtime.current_global_holding_coverage(
        **current,
        current_sell_book_witness_resolver=lambda _row: "sell-book-1",
    )
    assert covered.outcome is global_batch_runtime.GlobalHoldingCoverageOutcome.COVERED
    assert covered.coverage == evaluated
    assert covered.decision_log_id == 42
    assert global_batch_runtime.current_global_holding_coverage(
        **{**current, "probability_content_identity": "q-content-changed"},
        current_sell_book_witness_resolver=lambda _row: "sell-book-1",
    ).outcome is global_batch_runtime.GlobalHoldingCoverageOutcome.PROBABILITY_CONTENT
    for changed_content in (
        "q-content-source-changed",
        "q-content-alpha-changed",
        "q-content-band-changed",
    ):
        assert global_batch_runtime.current_global_holding_coverage(
            **{**current, "probability_content_identity": changed_content},
            current_sell_book_witness_resolver=lambda _row: "sell-book-1",
        ).outcome is global_batch_runtime.GlobalHoldingCoverageOutcome.PROBABILITY_CONTENT
    assert global_batch_runtime.current_global_holding_coverage(
        **{**current, "checked_at_utc": at + _dt.timedelta(seconds=31)},
        current_sell_book_witness_resolver=lambda _row: "sell-book-1",
    ).outcome is global_batch_runtime.GlobalHoldingCoverageOutcome.COVERAGE_EXPIRED
    assert global_batch_runtime.current_global_holding_coverage(
        **current,
        current_sell_book_witness_resolver=lambda _row: "sell-book-changed",
    ).outcome is global_batch_runtime.GlobalHoldingCoverageOutcome.BOOK
    assert global_batch_runtime.current_global_holding_coverage(
        **{**current, "current_wealth_economic_identity": "wealth-2"},
        current_sell_book_witness_resolver=lambda _row: "sell-book-1",
    ).outcome is global_batch_runtime.GlobalHoldingCoverageOutcome.WEALTH
    global_batch_runtime._invalidate_global_holding_coverage_for_wealth(
        "wealth-2"
    )
    assert global_batch_runtime.current_global_holding_coverage(
        **current,
        current_sell_book_witness_resolver=lambda _row: "sell-book-1",
    ).outcome is global_batch_runtime.GlobalHoldingCoverageOutcome.COVERAGE_NOT_PUBLISHED

    excluded = replace(
        evaluated,
        probability_witness_identity=None,
        probability_content_identity=None,
        status="EXCLUDED",
        candidate_id=None,
        candidate_ids=(),
        reason="SELL_ASSET_NOT_EXECUTABLE",
        sell_book_witness_identity=None,
    )
    global_batch_runtime._publish_global_holding_coverage(
        (excluded,),
        expected_obligations=(obligation,),
        probability_witnesses={"family-1": probability},
        decision_log_id=43,
    )
    assert global_batch_runtime.current_global_holding_coverage(
        **current,
        current_sell_book_witness_resolver=lambda _row: "sell-book-1",
    ).outcome is global_batch_runtime.GlobalHoldingCoverageOutcome.COVERAGE_PARTITION


def test_probability_content_identity_excludes_only_receipt_time_and_certificate():
    bindings = (
        OutcomeTokenBinding(
            bin_id="20C",
            condition_id="condition-20",
            yes_token_id="yes-20",
            no_token_id="no-20",
        ),
        OutcomeTokenBinding(
            bin_id="21C",
            condition_id="condition-21",
            yes_token_id="yes-21",
            no_token_id="no-21",
        ),
    )
    point = np.array([0.4, 0.6])
    samples = np.tile(point, (100, 1))
    stable = dict(
        family_key="City|2026-07-24|high",
        bindings=bindings,
        q_version="q-version",
        resolution_identity="resolution",
        topology_identity="topology",
        posterior_identity_hash="posterior",
        source_truth_identity="source",
        band_alpha=0.05,
        band_basis="finite-current-evidence",
        yes_point_q=point,
        yes_q_samples=samples,
    )
    content = joint_probability_content_identity(**stable)
    first = joint_probability_witness_identity(
        **stable,
        authority_certificate_hash="certificate-a",
        captured_at_utc=_dt.datetime(
            2026, 7, 24, 5, 36, tzinfo=_dt.timezone.utc
        ),
    )
    second = joint_probability_witness_identity(
        **stable,
        authority_certificate_hash="certificate-b",
        captured_at_utc=_dt.datetime(
            2026, 7, 24, 5, 37, tzinfo=_dt.timezone.utc
        ),
    )

    assert first != second
    assert joint_probability_content_identity(**stable) == content
    changed_samples = samples.copy()
    changed_samples[0] = np.array([0.5, 0.5])
    assert joint_probability_content_identity(
        **{**stable, "yes_q_samples": changed_samples}
    ) != content
    assert joint_probability_content_identity(
        **{**stable, "source_truth_identity": "source-changed"}
    ) != content
    assert joint_probability_content_identity(
        **{**stable, "topology_identity": "topology-changed"}
    ) != content


def test_global_auction_receipt_preserves_book_states_with_zero_evaluations():
    conn = sqlite3.connect(":memory:")
    conn.row_factory = sqlite3.Row
    conn.execute(
        """
        CREATE TABLE decision_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            mode TEXT NOT NULL,
            started_at TEXT NOT NULL,
            completed_at TEXT NOT NULL,
            artifact_json TEXT NOT NULL,
            timestamp TEXT NOT NULL,
            env TEXT NOT NULL
        )
        """
    )
    decision = GlobalSingleOrderDecision(
        candidate=None,
        shares=Decimal("0"),
        cost_usd=Decimal("0"),
        robust_delta_log_wealth=0.0,
        robust_ev_usd=0.0,
        capital_efficiency=0.0,
        no_trade_reason="NO_CURRENT_EXECUTABLE_POSITIVE_ORDER",
        rejection_reasons={},
        candidate_evaluations=(),
        candidate_input_count=0,
    )
    at = _dt.datetime(2026, 7, 16, 18, 0, tzinfo=_dt.timezone.utc)
    row_id = global_batch_runtime._store_global_auction_receipt(
        conn,
        selected=SimpleNamespace(decision=decision),
        selection_epoch_identity="epoch-empty-current",
        selection_cut_at_utc=at,
        decision_at_utc=at + _dt.timedelta(seconds=1),
        probability_manifest=(("family-empty", "q-empty"),),
        full_scope_identity="full-scope-empty-current",
        full_scope_family_keys=("family-empty",),
        probability_ineligible_by_family={},
        book_epoch_identity="book-empty-current",
        book_asset_count=1,
        book_asset_states=(
            (
                "family-empty",
                "20C",
                "condition-empty",
                "YES",
                "yes-empty",
                "NO_ASK",
                "book-empty-yes",
                "event-empty",
                "gamma-empty",
                "False",
            ),
            (
                "family-empty",
                "20C",
                "condition-empty",
                "NO",
                "no-empty",
                "VENUE_NOT_EXECUTABLE",
                "metadata-empty-no",
                "event-empty",
                "gamma-empty",
                "False",
            ),
        ),
        wealth_witness=_test_receipt_wealth_witness(
            witness_identity="wealth-empty-current",
            economic_identity="wealth-economics-empty-current",
        ),
        fractional_kelly_multiplier=Decimal("0.25"),
        book_captured_at_utc=at,
        book_max_age=_dt.timedelta(seconds=30),
    )

    artifact = json.loads(
        conn.execute(
            "SELECT artifact_json FROM decision_log WHERE id = ?",
            (row_id,),
        ).fetchone()["artifact_json"]
    )
    summary = artifact["summary"]
    assert summary["candidate_evaluation_count"] == 0
    assert summary["candidate_coverage_complete"] is True
    assert summary["book_native_side_candidate_coverage_status"] == "COMPLETE"
    assert summary["book_native_side_candidate_coverage_complete"] is True
    assert summary["book_native_side_state_count"] == 2
    assert summary["book_native_side_executable_count"] == 0
    assert summary["book_native_side_non_executable_count"] == 2


def test_global_auction_receipt_reuses_unchanged_heavy_no_trade_payload(
    tmp_path,
    monkeypatch,
):
    db_path = tmp_path / "trade.db"
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    conn.execute(
        """
        CREATE TABLE decision_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            mode TEXT NOT NULL,
            started_at TEXT NOT NULL,
            completed_at TEXT NOT NULL,
            artifact_json TEXT NOT NULL,
            timestamp TEXT NOT NULL,
            env TEXT NOT NULL
        )
        """
    )
    families = tuple(f"family-{index}" for index in range(48))
    evaluations = tuple(
        GlobalSingleOrderCandidateEvaluation(
            candidate_id=f"candidate-{index}-{side.lower()}",
            family_key=family_key,
            bin_id=f"bin-{index}",
            condition_id=f"condition-{index}",
            side=side,
            token_id=f"token-{index}-{side.lower()}",
            action="BUY",
            status="REJECTED",
            rejection_reason="NO_ASK",
        )
        for index, family_key in enumerate(families)
        for side in ("YES", "NO")
    )
    decision = GlobalSingleOrderDecision(
        candidate=None,
        shares=Decimal("0"),
        cost_usd=Decimal("0"),
        robust_delta_log_wealth=0.0,
        robust_ev_usd=0.0,
        capital_efficiency=0.0,
        no_trade_reason="NO_CURRENT_EXECUTABLE_POSITIVE_ORDER",
        rejection_reasons={row.candidate_id: "NO_ASK" for row in evaluations},
        candidate_evaluations=evaluations,
        candidate_input_count=len(evaluations),
    )
    selected = SimpleNamespace(decision=decision)
    at = _dt.datetime(2026, 7, 17, 6, 0, tzinfo=_dt.timezone.utc)
    book_states = tuple(
        (
            family_key,
            f"bin-{index}",
            f"condition-{index}",
            side,
            f"token-{index}-{side.lower()}",
            "EXECUTABLE",
            f"book-{index}-{side.lower()}",
            f"event-{index}",
            f"gamma-{index}",
            "False",
        )
        for index, family_key in enumerate(families)
        for side in ("YES", "NO")
    )

    def store(
        *,
        suffix: str,
        current_selected: object = selected,
        current_book_states: tuple[tuple[str, ...], ...] = book_states,
        book_available: bool = True,
    ) -> int:
        row_id = global_batch_runtime._store_global_auction_receipt(
            conn,
            selected=current_selected,
            selection_epoch_identity=f"epoch-{suffix}",
            selection_cut_at_utc=at,
            decision_at_utc=at + _dt.timedelta(seconds=1),
            probability_manifest=tuple(
                (family_key, f"q-{suffix}-{index}")
                for index, family_key in enumerate(families)
            ),
            full_scope_identity="full-scope-empty-current",
            full_scope_family_keys=families,
            probability_ineligible_by_family={},
            book_epoch_identity=f"book-{suffix}",
            book_asset_count=len(families),
            book_asset_states=(current_book_states if book_available else ()),
            wealth_witness=_test_receipt_wealth_witness(
                witness_identity=f"wealth-{suffix}",
                economic_identity="wealth-economics-current",
            ),
            fractional_kelly_multiplier=Decimal("0.25"),
            book_captured_at_utc=(at if book_available else None),
            book_max_age=(
                _dt.timedelta(seconds=30) if book_available else None
            ),
        )
        assert row_id is not None
        return row_id

    full_row_id = store(suffix="first")
    conn.commit()
    conn.close()
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    duplicate_row_id = store(suffix="second")
    rows = conn.execute(
        "SELECT id, mode, artifact_json FROM decision_log ORDER BY id"
    ).fetchall()
    assert [row["mode"] for row in rows] == [
        "global_single_order_auction",
        "global_single_order_auction_delta",
    ]
    full_summary = json.loads(rows[0]["artifact_json"])["summary"]
    duplicate_summary = json.loads(rows[1]["artifact_json"])["summary"]
    full_candidate_payload = json.loads(
        zlib.decompress(
            base64.b64decode(full_summary["candidate_evaluations_zlib_b64"])
        )
    )
    rejection_indexes = [
        index
        for group in full_candidate_payload["rejected_groups"]
        for index in group["candidate_indexes"]
    ]
    assert sorted(rejection_indexes) == list(
        range(len(full_candidate_payload["buy_candidate_index"]))
    )
    assert all(
        "candidate_ids" not in group
        for group in full_candidate_payload["rejected_groups"]
    )
    assert full_row_id == rows[0]["id"]
    assert duplicate_row_id == rows[1]["id"]
    assert duplicate_summary["payload_compacted"] is True
    assert duplicate_summary["payload_reference_decision_log_id"] == full_row_id
    assert duplicate_summary["payload_reference_receipt_hash"] == (
        full_summary["receipt_hash"]
    )
    assert "probability_manifest" not in duplicate_summary
    context_delta = json.loads(
        zlib.decompress(
            base64.b64decode(
                duplicate_summary["audit_context_delta_zlib_b64"]
            )
        )
    )
    base_context = json.loads(
        zlib.decompress(
            base64.b64decode(full_summary["audit_context_zlib_b64"])
        )
    )
    reconstructed_context = global_batch_runtime._apply_json_object_delta(
        base_context,
        context_delta,
    )
    assert reconstructed_context["probability_manifest"][0] == [
        "family-0",
        "q-second-0",
    ]
    assert hashlib.sha256(
        global_batch_runtime._canonical_json_bytes(reconstructed_context)
    ).hexdigest() == duplicate_summary["audit_context_sha256"]
    assert duplicate_summary["wealth_witness_identity"] == "wealth-second"
    for field in global_batch_runtime._GLOBAL_AUCTION_HEAVY_RECEIPT_FIELDS:
        assert field in full_summary
        assert field not in duplicate_summary
    assert len(rows[1]["artifact_json"]) < len(rows[0]["artifact_json"])

    unavailable_row_id = store(
        suffix="book-unavailable",
        book_available=False,
    )
    unavailable_row = conn.execute(
        "SELECT mode, artifact_json FROM decision_log WHERE id = ?",
        (unavailable_row_id,),
    ).fetchone()
    unavailable_summary = json.loads(
        unavailable_row["artifact_json"]
    )["summary"]
    assert unavailable_row["mode"] == "global_single_order_auction_delta"
    assert unavailable_summary[
        "book_native_side_candidate_coverage_status"
    ] == "UNAVAILABLE"
    assert unavailable_summary["book_native_side_state_count"] == 0
    assert "book_native_side_states_zlib_b64" in unavailable_summary
    assert "book_native_side_delta_zlib_b64" not in unavailable_summary
    unavailable_payload = json.loads(
        zlib.decompress(
            base64.b64decode(
                unavailable_summary["book_native_side_states_zlib_b64"]
            )
        )
    )
    assert unavailable_payload == {
        "fields": list(global_batch_runtime._BOOK_NATIVE_SIDE_STATE_FIELDS),
        "rows": [],
    }
    connection_key = global_batch_runtime._decision_log_connection_key(conn)
    assert global_batch_runtime._GLOBAL_AUCTION_PAYLOAD_REFS[
        connection_key
    ].book.row_id == full_row_id

    with pytest.raises(
        ValueError,
        match="GLOBAL_AUCTION_RECEIPT_BOOK_SIDE_STATE_INVALID",
    ):
        global_batch_runtime._book_native_side_receipt(
            asset_states=(("malformed",),),
            probability_keys=(),
            buy_candidate_index=(),
            excluded_by_family={},
            required=False,
        )

    original_canonical_json_bytes = global_batch_runtime._canonical_json_bytes
    monkeypatch.setattr(
        global_batch_runtime,
        "_canonical_json_bytes",
        lambda value: (
            original_canonical_json_bytes(value) + b"x" * 1_000_000
            if isinstance(value, dict) and value.get("payload_compacted") is True
            else original_canonical_json_bytes(value)
        ),
    )
    unavailable_full_row_id = store(
        suffix="book-unavailable-full-anchor",
        book_available=False,
    )
    assert conn.execute(
        "SELECT mode FROM decision_log WHERE id = ?",
        (unavailable_full_row_id,),
    ).fetchone()["mode"] == "global_single_order_auction"
    assert global_batch_runtime._GLOBAL_AUCTION_PAYLOAD_REFS[
        connection_key
    ].book.row_id == full_row_id
    monkeypatch.setattr(
        global_batch_runtime,
        "_canonical_json_bytes",
        original_canonical_json_bytes,
    )

    changed_book_states = (
        (*book_states[0][:6], "book-new-yes", *book_states[0][7:]),
        *book_states[1:],
    )
    changed_evaluations = (
        replace(evaluations[0], rejection_reason="VENUE_NOT_EXECUTABLE"),
        *evaluations[1:],
    )
    changed_selected = SimpleNamespace(
        decision=replace(
            decision,
            rejection_reasons={
                **decision.rejection_reasons,
                evaluations[0].candidate_id: "VENUE_NOT_EXECUTABLE",
            },
            candidate_evaluations=changed_evaluations,
        )
    )
    delta_row_id = store(
        suffix="book-changed",
        current_selected=changed_selected,
        current_book_states=changed_book_states,
    )
    delta_row = conn.execute(
        "SELECT mode, artifact_json FROM decision_log WHERE id = ?",
        (delta_row_id,),
    ).fetchone()
    delta_summary = json.loads(delta_row["artifact_json"])["summary"]
    assert delta_row["mode"] == "global_single_order_auction_delta"
    assert delta_summary["payload_reference_fields"] == [
        "buy_minimum_marketable_repairs_zlib_b64",
        "holding_auction_coverage_zlib_b64",
    ]
    assert delta_summary["book_native_side_base_decision_log_id"] == full_row_id
    assert delta_summary["book_native_side_delta_removed_count"] == 0
    assert delta_summary["book_native_side_delta_upsert_count"] == 1
    delta_json = zlib.decompress(
        base64.b64decode(delta_summary["book_native_side_delta_zlib_b64"])
    )
    assert hashlib.sha256(delta_json).hexdigest() == (
        delta_summary["book_native_side_delta_sha256"]
    )
    delta = json.loads(delta_json)
    base_book_side_states = json.loads(
        zlib.decompress(
            base64.b64decode(full_summary["book_native_side_states_zlib_b64"])
        )
    )
    reconstructed = {
        tuple(row[:5]): row for row in base_book_side_states["rows"]
    }
    for key in delta["removed_keys"]:
        reconstructed.pop(tuple(key))
    for row in delta["upsert_rows"]:
        reconstructed[tuple(row[:5])] = row
    reconstructed_json = json.dumps(
        {
            "fields": list(global_batch_runtime._BOOK_NATIVE_SIDE_STATE_FIELDS),
            "rows": sorted(reconstructed.values()),
        },
        sort_keys=True,
        separators=(",", ":"),
    ).encode()
    assert hashlib.sha256(reconstructed_json).hexdigest() == (
        delta_summary["book_native_side_states_sha256"]
    )
    candidate_delta = json.loads(
        zlib.decompress(
            base64.b64decode(
                delta_summary["candidate_evaluations_delta_zlib_b64"]
            )
        )
    )
    base_candidates = json.loads(
        zlib.decompress(
            base64.b64decode(full_summary["candidate_evaluations_zlib_b64"])
        )
    )
    assert delta_summary["candidate_evaluations_delta_encoding"] == (
        "zlib+base64+semantic-keyed-canonical-json-delta-v3"
    )
    reconstructed_candidates = (
        global_batch_runtime._apply_candidate_evaluations_delta(
        base_candidates,
        candidate_delta,
        )
    )
    assert hashlib.sha256(
        global_batch_runtime._canonical_json_bytes(reconstructed_candidates)
    ).hexdigest() == delta_summary["candidate_evaluations_sha256"]
    assert delta_summary["selection_epoch_identity"] == "epoch-book-changed"
    assert delta_summary["book_epoch_identity"] == "book-book-changed"
    assert delta_summary["wealth_witness_identity"] == "wealth-book-changed"
    assert len(delta_row["artifact_json"]) < len(rows[0]["artifact_json"])
    assert len(delta_summary["book_native_side_delta_zlib_b64"]) < len(
        full_summary["book_native_side_states_zlib_b64"]
    )

    refreshed_book_states = tuple(
        (*row[:6], f"book-refreshed-{index}", *row[7:])
        for index, row in enumerate(book_states)
    )
    refreshed_book_id = store(
        suffix="book-full-refresh",
        current_selected=changed_selected,
        current_book_states=refreshed_book_states,
    )
    refreshed_book_row = conn.execute(
        "SELECT mode, artifact_json FROM decision_log WHERE id = ?",
        (refreshed_book_id,),
    ).fetchone()
    refreshed_book_summary = json.loads(
        refreshed_book_row["artifact_json"]
    )["summary"]
    assert refreshed_book_row["mode"] == "global_single_order_auction_delta"
    assert "book_native_side_states_zlib_b64" in refreshed_book_summary

    next_book_states = (
        (
            *refreshed_book_states[0][:6],
            "book-refreshed-next",
            *refreshed_book_states[0][7:],
        ),
        *refreshed_book_states[1:],
    )
    next_book_id = store(
        suffix="book-next",
        current_selected=changed_selected,
        current_book_states=next_book_states,
    )
    next_book_summary = json.loads(
        conn.execute(
            "SELECT artifact_json FROM decision_log WHERE id = ?",
            (next_book_id,),
        ).fetchone()["artifact_json"]
    )["summary"]
    assert next_book_summary["book_native_side_base_decision_log_id"] == (
        refreshed_book_id
    )
    assert next_book_summary["book_native_side_base_mode"] == (
        "global_single_order_auction_delta"
    )
    assert next_book_summary["book_native_side_base_receipt_hash"] == (
        refreshed_book_summary["receipt_hash"]
    )

    refreshed_book_artifact = json.loads(
        conn.execute(
            "SELECT artifact_json FROM decision_log WHERE id = ?",
            (refreshed_book_id,),
        ).fetchone()["artifact_json"]
    )
    refreshed_book_artifact["summary"]["receipt_hash"] = "tampered-anchor"
    conn.execute(
        "UPDATE decision_log SET artifact_json = ? WHERE id = ?",
        (json.dumps(refreshed_book_artifact), refreshed_book_id),
    )
    tampered_anchor_recovery_id = store(
        suffix="tampered-anchor-recovery",
        current_selected=changed_selected,
        current_book_states=next_book_states,
    )
    assert conn.execute(
        "SELECT mode FROM decision_log WHERE id = ?",
        (tampered_anchor_recovery_id,),
    ).fetchone()["mode"] == "global_single_order_auction"

    connection_key = global_batch_runtime._decision_log_connection_key(conn)
    global_batch_runtime._GLOBAL_AUCTION_PAYLOAD_REFS.pop(connection_key, None)
    restart_anchor_id = store(
        suffix="restart-anchor",
        current_selected=changed_selected,
        current_book_states=next_book_states,
    )
    assert conn.execute(
        "SELECT mode FROM decision_log WHERE id = ?",
        (restart_anchor_id,),
    ).fetchone()["mode"] == "global_single_order_auction"

    conn.execute("DELETE FROM decision_log WHERE id = ?", (restart_anchor_id,))
    deleted_anchor_recovery_id = store(
        suffix="deleted-anchor-recovery",
        current_selected=changed_selected,
        current_book_states=next_book_states,
    )
    assert conn.execute(
        "SELECT mode FROM decision_log WHERE id = ?",
        (deleted_anchor_recovery_id,),
    ).fetchone()["mode"] == "global_single_order_auction"

    winner = SimpleNamespace(
        decision=SimpleNamespace(
            candidate=SimpleNamespace(candidate_id="winner"),
            candidate_evaluations=evaluations,
            candidate_input_count=len(evaluations),
            rejection_reasons=decision.rejection_reasons,
            no_trade_reason=None,
        ),
        winner_event_id="event-winner",
        actuation=SimpleNamespace(actuation_identity="actuation-winner"),
    )
    winner_row_id = store(suffix="winner", current_selected=winner)
    winner_mode = conn.execute(
        "SELECT mode FROM decision_log WHERE id = ?",
        (winner_row_id,),
    ).fetchone()["mode"]
    assert winner_mode == "global_single_order_auction_delta"
    winner_summary = json.loads(
        conn.execute(
            "SELECT artifact_json FROM decision_log WHERE id = ?",
            (winner_row_id,),
        ).fetchone()["artifact_json"]
    )["summary"]
    assert winner_summary["winner_candidate_id"] == "winner"
    assert winner_summary["payload_compacted"] is True
    assert "candidate_evaluations_delta_zlib_b64" in winner_summary
    assert winner_summary["payload_reference_decision_log_id"] == (
        deleted_anchor_recovery_id
    )
    assert "candidate_evaluations_zlib_b64" not in winner_summary
    assert "holding_auction_coverage_zlib_b64" not in winner_summary
    assert "buy_minimum_marketable_repairs_zlib_b64" not in winner_summary
    assert len(
        conn.execute(
            "SELECT artifact_json FROM decision_log WHERE id = ?",
            (winner_row_id,),
        ).fetchone()["artifact_json"]
    ) < len(rows[0]["artifact_json"])

    fallback_evaluations = (
        replace(evaluations[0], rejection_reason="BOOK_STALE"),
        *evaluations[1:],
    )
    fallback_selected = SimpleNamespace(
        decision=replace(
            decision,
            rejection_reasons={
                **decision.rejection_reasons,
                evaluations[0].candidate_id: "BOOK_STALE",
            },
            candidate_evaluations=fallback_evaluations,
        )
    )

    def reject_inexact_candidate_delta(**_kwargs):
        raise ValueError(
            "GLOBAL_AUCTION_RECEIPT_CANDIDATE_DELTA_HASH_MISMATCH"
        )

    with monkeypatch.context() as candidate_delta_patch:
        candidate_delta_patch.setattr(
            global_batch_runtime,
            "_candidate_evaluations_delta_receipt",
            reject_inexact_candidate_delta,
        )
        fallback_row_id = store(
            suffix="candidate-delta-mismatch",
            current_selected=fallback_selected,
        )
    fallback_summary = json.loads(
        conn.execute(
            "SELECT artifact_json FROM decision_log WHERE id = ?",
            (fallback_row_id,),
        ).fetchone()["artifact_json"]
    )["summary"]
    inline_candidate_json = zlib.decompress(
        base64.b64decode(
            fallback_summary["candidate_evaluations_zlib_b64"]
        )
    )
    assert hashlib.sha256(inline_candidate_json).hexdigest() == (
        fallback_summary["candidate_evaluations_sha256"]
    )
    assert "candidate_evaluations_delta_zlib_b64" not in fallback_summary
    assert "candidate_evaluations_base_decision_log_id" not in fallback_summary
    conn.close()


def test_global_auction_receipt_bounded_delta_chain_write_amplification(
    tmp_path,
    monkeypatch,
):
    monkeypatch.setattr(global_batch_runtime, "_GLOBAL_AUCTION_PAYLOAD_REFS", {})
    at = _dt.datetime(2026, 7, 31, 6, 0, tzinfo=_dt.timezone.utc)
    families = tuple(f"family-{index}" for index in range(96))
    evaluations = tuple(
        GlobalSingleOrderCandidateEvaluation(
            candidate_id=f"candidate-{index}-{side.lower()}",
            family_key=family_key,
            bin_id=f"bin-{index}",
            condition_id=f"condition-{index}",
            side=side,
            token_id=f"token-{index}-{side.lower()}",
            action="BUY",
            status="REJECTED",
            rejection_reason="NO_ASK",
        )
        for index, family_key in enumerate(families)
        for side in ("YES", "NO")
    )

    def blob(label: str) -> str:
        return "".join(
            hashlib.sha256(f"{label}-{part}".encode()).hexdigest()
            for part in range(8)
        )

    book_states = tuple(
        (
            family_key,
            f"bin-{index}",
            f"condition-{index}",
            side,
            f"token-{index}-{side.lower()}",
            "EXECUTABLE",
            blob(f"book-{index}-{side.lower()}"),
            f"event-{index}",
            f"gamma-{index}",
            "False",
        )
        for index, family_key in enumerate(families)
        for side in ("YES", "NO")
    )

    def current(step: int) -> tuple[object, tuple[tuple[str, ...], ...]]:
        changed_evaluations = tuple(
            replace(
                row,
                rejection_reason=(
                    f"VENUE_NOT_EXECUTABLE:{step}"
                    if index == 0
                    else "VENUE_NOT_EXECUTABLE"
                ),
            )
            if index < len(evaluations) // 2
            else row
            for index, row in enumerate(evaluations)
        )
        rejection_reasons = {
            row.candidate_id: row.rejection_reason for row in changed_evaluations
        }
        decision = GlobalSingleOrderDecision(
            candidate=None,
            shares=Decimal("0"),
            cost_usd=Decimal("0"),
            robust_delta_log_wealth=0.0,
            robust_ev_usd=0.0,
            capital_efficiency=0.0,
            no_trade_reason="NO_CURRENT_EXECUTABLE_POSITIVE_ORDER",
            rejection_reasons=rejection_reasons,
            candidate_evaluations=changed_evaluations,
            candidate_input_count=len(changed_evaluations),
        )
        changed_books = tuple(
            (
                *row[:6],
                (
                    blob(f"book-step-{step}")
                    if index == 0
                    else blob(f"changed-{index}")
                ),
                *row[7:],
            )
            if index < (len(book_states) * 2) // 5
            else row
            for index, row in enumerate(book_states)
        )
        return SimpleNamespace(decision=decision), changed_books

    def create_conn(path):
        conn = sqlite3.connect(path)
        conn.row_factory = sqlite3.Row
        conn.execute(
            """
            CREATE TABLE decision_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                mode TEXT NOT NULL,
                started_at TEXT NOT NULL,
                completed_at TEXT NOT NULL,
                artifact_json TEXT NOT NULL,
                timestamp TEXT NOT NULL,
                env TEXT NOT NULL
            )
            """
        )
        return conn

    def store(
        conn,
        *,
        suffix: str,
        selected: object,
        states: tuple[tuple[str, ...], ...],
    ) -> int:
        row_id = global_batch_runtime._store_global_auction_receipt(
            conn,
            selected=selected,
            selection_epoch_identity=f"epoch-{suffix}",
            selection_cut_at_utc=at,
            decision_at_utc=at + _dt.timedelta(seconds=1),
            probability_manifest=tuple(
                (family, f"q-{suffix}-{index}")
                for index, family in enumerate(families)
            ),
            full_scope_identity="full-scope",
            full_scope_family_keys=families,
            probability_ineligible_by_family={},
            book_epoch_identity=f"book-{suffix}",
            book_asset_count=len(families),
            book_asset_states=states,
            wealth_witness=_test_receipt_wealth_witness(
                witness_identity=f"wealth-{suffix}",
                economic_identity="wealth-current",
            ),
            fractional_kelly_multiplier=Decimal("0.25"),
            book_captured_at_utc=at,
            book_max_age=_dt.timedelta(seconds=30),
        )
        assert row_id is not None
        return row_id

    def run(path, *, fixed_anchor: bool):
        conn = create_conn(path)
        base_decision = GlobalSingleOrderDecision(
            candidate=None,
            shares=Decimal("0"),
            cost_usd=Decimal("0"),
            robust_delta_log_wealth=0.0,
            robust_ev_usd=0.0,
            capital_efficiency=0.0,
            no_trade_reason="NO_CURRENT_EXECUTABLE_POSITIVE_ORDER",
            rejection_reasons={
                row.candidate_id: row.rejection_reason for row in evaluations
            },
            candidate_evaluations=evaluations,
            candidate_input_count=len(evaluations),
        )
        store(
            conn,
            suffix="anchor",
            selected=SimpleNamespace(decision=base_decision),
            states=book_states,
        )
        key = global_batch_runtime._decision_log_connection_key(conn)
        anchor_ref = global_batch_runtime._GLOBAL_AUCTION_PAYLOAD_REFS[key]
        rows = []
        for step in range(1, 9):
            if fixed_anchor:
                global_batch_runtime._GLOBAL_AUCTION_PAYLOAD_REFS[key] = anchor_ref
            selected, states = current(step)
            row_id = store(
                conn,
                suffix=f"step-{step}",
                selected=selected,
                states=states,
            )
            row = conn.execute(
                "SELECT artifact_json FROM decision_log WHERE id = ?",
                (row_id,),
            ).fetchone()
            summary = json.loads(row["artifact_json"])["summary"]
            rows.append((row_id, len(row["artifact_json"]), summary))
        return conn, rows

    fixed_conn, fixed_rows = run(tmp_path / "fixed.db", fixed_anchor=True)
    rolling_conn, rolling_rows = run(tmp_path / "rolling.db", fixed_anchor=False)
    fixed_bytes = sum(row[1] for row in fixed_rows)
    rolling_bytes = sum(row[1] for row in rolling_rows)
    assert rolling_bytes <= fixed_bytes * 0.65
    assert [
        row[2]["candidate_evaluations_delta_chain_depth"]
        for row in rolling_rows
    ] == list(range(1, 9))
    assert [
        row[2]["book_native_side_delta_chain_depth"] for row in rolling_rows
    ] == list(range(1, 9))
    assert [
        row[2]["audit_context_delta_chain_depth"] for row in rolling_rows
    ] == list(range(1, 9))

    def reconstruct_book(
        summary: Mapping[str, object],
        seen: frozenset[int] = frozenset(),
    ) -> list[list[str]]:
        if "book_native_side_states_zlib_b64" in summary:
            payload = json.loads(
                zlib.decompress(
                    base64.b64decode(
                        str(summary["book_native_side_states_zlib_b64"])
                    )
                )
            )
            return payload["rows"]
        base_id = int(summary["book_native_side_base_decision_log_id"])
        assert base_id not in seen
        row = rolling_conn.execute(
            "SELECT artifact_json FROM decision_log WHERE id = ?",
            (base_id,),
        ).fetchone()
        assert row is not None
        base_summary = json.loads(row["artifact_json"])["summary"]
        base_rows = reconstruct_book(base_summary, seen | {base_id})
        current = {tuple(row[:5]): row for row in base_rows}
        delta = json.loads(
            zlib.decompress(
                base64.b64decode(
                    str(summary["book_native_side_delta_zlib_b64"])
                )
            )
        )
        for key in delta["removed_keys"]:
            current.pop(tuple(key))
        for row in delta["upsert_rows"]:
            current[tuple(row[:5])] = row
        return sorted(current.values())

    for _, _, summary in rolling_rows:
        candidates = live_health._current_global_auction_candidate_payload(
            rolling_conn,
            summary,
        )
        assert hashlib.sha256(
            global_batch_runtime._canonical_json_bytes(candidates)
        ).hexdigest() == summary["candidate_evaluations_sha256"]
        reconstructed_books = {
            "fields": list(global_batch_runtime._BOOK_NATIVE_SIDE_STATE_FIELDS),
            "rows": reconstruct_book(summary),
        }
        assert hashlib.sha256(
            global_batch_runtime._canonical_json_bytes(reconstructed_books)
        ).hexdigest() == summary["book_native_side_states_sha256"]

    selected, states = current(9)
    boundary_id = store(
        rolling_conn,
        suffix="step-9",
        selected=selected,
        states=states,
    )
    boundary_summary = json.loads(
        rolling_conn.execute(
            "SELECT artifact_json FROM decision_log WHERE id = ?",
            (boundary_id,),
        ).fetchone()["artifact_json"]
    )["summary"]
    assert "candidate_evaluations_zlib_b64" in boundary_summary
    assert "book_native_side_states_zlib_b64" in boundary_summary
    rolling_ref = global_batch_runtime._GLOBAL_AUCTION_PAYLOAD_REFS[
        global_batch_runtime._decision_log_connection_key(rolling_conn)
    ]
    assert rolling_ref.candidate.delta_depth == 0
    assert rolling_ref.book.delta_depth == 0
    assert rolling_ref.audit_context.delta_depth == 0

    holding_conn = create_conn(tmp_path / "holding.db")
    holding_payload = [
        {
            "position_id": f"position-{index:02d}",
            "status": "EXCLUDED",
            "reason": "PROBABILITY_AUTHORITY_UNAVAILABLE:0",
            "stable_evidence": blob(f"holding-{index}"),
        }
        for index in range(32)
    ]
    holding_raw = global_batch_runtime._canonical_json_bytes(holding_payload)
    holding_summary: Mapping[str, object] = {
        "receipt_hash": "holding-receipt-0",
        "holding_auction_coverage_encoding": (
            "zlib+base64+canonical-json-v2"
        ),
        "holding_auction_coverage_sha256": hashlib.sha256(
            holding_raw
        ).hexdigest(),
        "holding_auction_coverage_zlib_b64": base64.b64encode(
            zlib.compress(holding_raw, level=9)
        ).decode("ascii"),
    }
    holding_conn.execute(
        """
        INSERT INTO decision_log
            (mode, started_at, completed_at, artifact_json, timestamp, env)
        VALUES (?, ?, ?, ?, ?, ?)
        """,
        (
            "global_single_order_auction",
            at.isoformat(),
            at.isoformat(),
            json.dumps({"summary": holding_summary}),
            at.isoformat(),
            "live",
        ),
    )
    base_id = int(holding_conn.execute("SELECT last_insert_rowid()").fetchone()[0])
    base_mode = "global_single_order_auction"
    base_hash = "holding-receipt-0"
    base_sha = str(holding_summary["holding_auction_coverage_sha256"])
    for step in range(1, 9):
        current_holding = [dict(row) for row in holding_payload]
        current_holding[0]["reason"] = (
            f"PROBABILITY_AUTHORITY_UNAVAILABLE:{step}"
        )
        current_sha = hashlib.sha256(
            global_batch_runtime._canonical_json_bytes(current_holding)
        ).hexdigest()
        delta = global_batch_runtime._keyed_object_list_delta_receipt(
            prefix="holding_auction_coverage",
            key_field="position_id",
            base_rows=holding_payload,
            current_rows=current_holding,
            expected_sha256=current_sha,
        )
        receipt_hash = f"holding-receipt-{step}"
        holding_summary = {
            "receipt_hash": receipt_hash,
            "holding_auction_coverage_encoding": (
                "zlib+base64+canonical-json-v2"
            ),
            "holding_auction_coverage_sha256": current_sha,
            **delta,
            "holding_auction_coverage_base_decision_log_id": base_id,
            "holding_auction_coverage_base_mode": base_mode,
            "holding_auction_coverage_base_receipt_hash": base_hash,
            "holding_auction_coverage_base_sha256": base_sha,
            "holding_auction_coverage_delta_chain_depth": step,
        }
        holding_conn.execute(
            """
            INSERT INTO decision_log
                (mode, started_at, completed_at, artifact_json, timestamp, env)
            VALUES (?, ?, ?, ?, ?, ?)
            """,
            (
                "global_single_order_auction_delta",
                at.isoformat(),
                at.isoformat(),
                json.dumps({"summary": holding_summary}),
                at.isoformat(),
                "live",
            ),
        )
        base_id = int(
            holding_conn.execute("SELECT last_insert_rowid()").fetchone()[0]
        )
        base_mode = "global_single_order_auction_delta"
        base_hash = receipt_hash
        base_sha = current_sha
        holding_payload = current_holding
        reconstructed = live_health._current_global_auction_holding_payload(
            holding_conn,
            holding_summary,
        )
        assert reconstructed == holding_payload
    over_depth = dict(holding_summary)
    over_depth["holding_auction_coverage_delta_chain_depth"] = 9
    with pytest.raises(ValueError, match="REFERENCE_DEPTH"):
        live_health._current_global_auction_holding_payload(
            holding_conn,
            over_depth,
        )
    missing_base = dict(holding_summary)
    missing_base["holding_auction_coverage_base_decision_log_id"] = 999_999
    missing_base["holding_auction_coverage_delta_chain_depth"] = 1
    with pytest.raises(ValueError, match="REFERENCE_ROW"):
        live_health._current_global_auction_holding_payload(
            holding_conn,
            missing_base,
        )
    cyclic = dict(holding_summary)
    cyclic.update(
        {
            "holding_auction_coverage_base_decision_log_id": base_id,
            "holding_auction_coverage_base_mode": (
                "global_single_order_auction_delta"
            ),
            "holding_auction_coverage_base_receipt_hash": base_hash,
            "holding_auction_coverage_base_sha256": base_sha,
            "holding_auction_coverage_delta_chain_depth": 1,
        }
    )
    holding_conn.execute(
        "UPDATE decision_log SET artifact_json = ? WHERE id = ?",
        (json.dumps({"summary": cyclic}), base_id),
    )
    with pytest.raises(ValueError, match="REFERENCE_(?:CYCLE|DEPTH)"):
        live_health._current_global_auction_holding_payload(
            holding_conn,
            cyclic,
        )

    fixed_conn.close()
    rolling_conn.close()
    holding_conn.close()


def test_global_auction_holding_delta_reconstructs_current_epoch_exactly():
    base = [
        {
            "position_id": "position-a",
            "decision_at_utc": "2026-07-20 00:00:00+00:00",
            "book_epoch_identity": "book-a",
            "probability_witness_identity": "q-a",
            "status": "EVALUATED",
        },
        {
            "position_id": "position-b",
            "decision_at_utc": "2026-07-20 00:00:00+00:00",
            "book_epoch_identity": "book-a",
            "probability_witness_identity": "q-b",
            "status": "EVALUATED",
        },
    ]
    current = [
        {
            **base[0],
            "decision_at_utc": "2026-07-20 00:00:02+00:00",
            "book_epoch_identity": "book-b",
            "probability_witness_identity": "q-a-current",
        },
        {
            **base[1],
            "decision_at_utc": "2026-07-20 00:00:02+00:00",
            "book_epoch_identity": "book-b",
        },
    ]
    current_sha = hashlib.sha256(
        global_batch_runtime._canonical_json_bytes(current)
    ).hexdigest()
    receipt = global_batch_runtime._keyed_object_list_delta_receipt(
        prefix="holding_auction_coverage",
        key_field="position_id",
        base_rows=base,
        current_rows=current,
        expected_sha256=current_sha,
    )
    encoded = zlib.decompress(
        base64.b64decode(
            receipt["holding_auction_coverage_delta_zlib_b64"]
        )
    )
    assert hashlib.sha256(encoded).hexdigest() == receipt[
        "holding_auction_coverage_delta_sha256"
    ]
    reconstructed = global_batch_runtime._apply_keyed_object_list_delta(
        base,
        json.loads(encoded),
    )
    assert reconstructed == current
    assert hashlib.sha256(
        global_batch_runtime._canonical_json_bytes(reconstructed)
    ).hexdigest() == current_sha


def test_global_auction_payload_cache_rejects_rolled_back_row_id_reuse(
    tmp_path,
    monkeypatch,
):
    monkeypatch.setattr(global_batch_runtime, "_GLOBAL_AUCTION_PAYLOAD_REFS", {})
    db_path = tmp_path / "rollback-reuse.db"
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    conn.execute(
        """
        CREATE TABLE decision_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            mode TEXT NOT NULL,
            started_at TEXT NOT NULL,
            completed_at TEXT NOT NULL,
            artifact_json TEXT NOT NULL,
            timestamp TEXT NOT NULL,
            env TEXT NOT NULL
        )
        """
    )
    conn.commit()
    at = _dt.datetime(2026, 7, 20, 1, 0, tzinfo=_dt.timezone.utc)
    selected = SimpleNamespace(
        decision=GlobalSingleOrderDecision(
            candidate=None,
            shares=Decimal("0"),
            cost_usd=Decimal("0"),
            robust_delta_log_wealth=0.0,
            robust_ev_usd=0.0,
            capital_efficiency=0.0,
            no_trade_reason="NO_CURRENT_EXECUTABLE_POSITIVE_ORDER",
            rejection_reasons={},
            candidate_evaluations=(),
            candidate_input_count=0,
        )
    )

    def store(suffix: str) -> int:
        row_id = global_batch_runtime._store_global_auction_receipt(
            conn,
            selected=selected,
            selection_epoch_identity=f"epoch-{suffix}",
            selection_cut_at_utc=at,
            decision_at_utc=at,
            probability_manifest=(),
            full_scope_identity="scope-empty",
            full_scope_family_keys=(),
            probability_ineligible_by_family={},
            book_epoch_identity=f"book-{suffix}",
            book_asset_count=None,
            book_asset_states=(),
            wealth_witness=_test_receipt_wealth_witness(
                witness_identity=f"wealth-{suffix}",
                economic_identity="wealth-current",
            ),
            fractional_kelly_multiplier=Decimal("0.25"),
        )
        assert row_id is not None
        return row_id

    rolled_back_id = store("rolled-back")
    conn.rollback()
    conn.execute(
        "INSERT INTO decision_log VALUES (?, ?, ?, ?, ?, ?, ?)",
        (
            rolled_back_id,
            "global_single_order_auction",
            at.isoformat(),
            at.isoformat(),
            json.dumps({"summary": {"receipt_hash": "replacement-row"}}),
            at.isoformat(),
            "live",
        ),
    )
    conn.commit()

    current_id = store("current")
    current_mode = conn.execute(
        "SELECT mode FROM decision_log WHERE id = ?",
        (current_id,),
    ).fetchone()["mode"]
    assert current_mode == "global_single_order_auction"
    assert current_id != rolled_back_id
    current_ref = global_batch_runtime._GLOBAL_AUCTION_PAYLOAD_REFS[
        str(db_path)
    ]
    assert current_ref.candidate.row_id == current_id
    conn.close()


