def test_current_gamma_market_fetch_batches_concurrently_and_fails_closed():
    condition_ids = tuple(f"condition-{index}" for index in range(205))
    barrier = threading.Barrier(3)
    chunks = []
    lock = threading.Lock()

    def gamma_get(path, *, params, timeout):
        assert path == "/markets"
        assert timeout == 4.0
        chunk = tuple(params["condition_ids"])
        assert params["limit"] == len(chunk)
        with lock:
            chunks.append(chunk)
        barrier.wait(timeout=2.0)
        return SimpleNamespace(
            status_code=200,
            json=lambda: [{"conditionId": condition_id} for condition_id in chunk],
        )

    markets, request_count = universe.fetch_current_gamma_markets(
        condition_ids,
        gamma_get=gamma_get,
        timeout=4.0,
        max_workers=3,
    )
    assert request_count == 3
    assert sorted(map(len, chunks)) == [5, 100, 100]
    assert {market["conditionId"] for market in markets} == set(condition_ids)

    def response(payload, status_code=200):
        return SimpleNamespace(status_code=status_code, json=lambda: payload)

    with pytest.raises(ValueError, match="GLOBAL_CURRENT_GAMMA_MARKETS_HTTP:503"):
        universe.fetch_current_gamma_markets(
            ("condition-0",),
            gamma_get=lambda *_args, **_kwargs: response([], 503),
            timeout=4.0,
        )
    with pytest.raises(
        ValueError, match="GLOBAL_CURRENT_GAMMA_MARKETS_RESPONSE_INVALID"
    ):
        universe.fetch_current_gamma_markets(
            ("condition-0",),
            gamma_get=lambda *_args, **_kwargs: response({}),
            timeout=4.0,
        )
    with pytest.raises(ValueError, match="GLOBAL_CURRENT_GAMMA_MARKET_INVALID"):
        universe.fetch_current_gamma_markets(
            ("condition-0",),
            gamma_get=lambda *_args, **_kwargs: response([None]),
            timeout=4.0,
        )

    def worker_error(_path, *, params, timeout):
        del timeout
        if "condition-100" in params["condition_ids"]:
            raise RuntimeError("worker failed")
        return response([])

    with pytest.raises(RuntimeError, match="worker failed"):
        universe.fetch_current_gamma_markets(
            tuple(f"condition-{index}" for index in range(101)),
            gamma_get=worker_error,
            timeout=4.0,
            max_workers=2,
        )


def test_current_gamma_market_fetch_returns_before_late_workers_at_total_deadline(monkeypatch):
    import concurrent.futures

    real_executor = concurrent.futures.ThreadPoolExecutor
    shutdown_started = threading.Event()
    first_worker_entered = threading.Event()
    second_worker_waiting = threading.Event()
    allow_second_worker = threading.Event()
    workers_started = threading.Event()
    completion_wait_entered = threading.Event()
    deadline_triggered = threading.Event()
    worker_release = threading.Event()
    workers_finished = threading.Event()
    call_finished = threading.Event()
    outcome = []
    started_chunks = []
    finished_chunks = []
    arrived_chunks = []
    calls_lock = threading.Lock()
    clock = [0.0]
    shutdown_calls = []

    class TrackingExecutor(real_executor):
        def shutdown(self, *args, **kwargs):
            shutdown_started.set()
            shutdown_calls.append((args, kwargs))
            return super().shutdown(*args, **kwargs)

    monkeypatch.setattr(concurrent.futures, "ThreadPoolExecutor", TrackingExecutor)
    monkeypatch.setattr(
        universe,
        "_time",
        SimpleNamespace(monotonic=lambda: clock[0]),
    )

    def controlled_as_completed(_futures, *, timeout):
        assert timeout == pytest.approx(1.0)
        completion_wait_entered.set()
        assert deadline_triggered.wait(2.0)
        raise concurrent.futures.TimeoutError

    monkeypatch.setattr(concurrent.futures, "as_completed", controlled_as_completed)

    def slow_gamma_get(_path, *, params, timeout):
        assert timeout == pytest.approx(1.0)
        chunk = tuple(params["condition_ids"])
        with calls_lock:
            arrived_chunks.append(chunk)
            arrival_index = len(arrived_chunks)
        if arrival_index == 2:
            second_worker_waiting.set()
            assert allow_second_worker.wait(2.0)
        with calls_lock:
            started_chunks.append(chunk)
            if arrival_index == 1:
                first_worker_entered.set()
            if len(started_chunks) == 2:
                workers_started.set()
        try:
            assert worker_release.wait(2.0)
            return SimpleNamespace(status_code=200, json=lambda: [])
        finally:
            with calls_lock:
                finished_chunks.append(chunk)
                if len(finished_chunks) == 2:
                    workers_finished.set()

    def invoke():
        try:
            universe.fetch_current_gamma_markets(
                tuple(f"condition-{index}" for index in range(101)),
                gamma_get=slow_gamma_get,
                timeout=4.0,
                total_timeout=1.0,
                max_workers=2,
            )
        except BaseException as exc:  # noqa: BLE001 - thread result assertion below
            outcome.append(exc)
        finally:
            call_finished.set()

    caller = threading.Thread(target=invoke, daemon=True)
    caller.start()
    try:
        assert first_worker_entered.wait(2.0)
        assert second_worker_waiting.wait(2.0)
        assert not call_finished.is_set()
        allow_second_worker.set()
        assert workers_started.wait(2.0)
        assert completion_wait_entered.wait(2.0)
        clock[0] = 1.0
        deadline_triggered.set()
        assert shutdown_started.wait(2.0)
        assert call_finished.wait(2.0)
        assert not workers_finished.is_set()
    finally:
        allow_second_worker.set()
        deadline_triggered.set()
        worker_release.set()
    assert workers_finished.wait(2.0)
    assert call_finished.wait(2.0)
    caller.join(2.0)
    assert sorted(finished_chunks) == sorted(started_chunks)
    assert len(started_chunks) == 2
    assert shutdown_calls == [((), {"wait": False, "cancel_futures": True})]
    assert len(outcome) == 1
    assert isinstance(outcome[0], ValueError)
    assert "GLOBAL_CURRENT_GAMMA_MARKETS_DEADLINE_EXCEEDED" in str(outcome[0])


def test_current_gamma_client_survives_late_batch_workers(monkeypatch):
    import httpx

    clients = []

    class FakeClient:
        is_closed = False

        def __init__(self, **kwargs):
            self.kwargs = kwargs
            clients.append(self)

    monkeypatch.setattr(era, "_GLOBAL_CURRENT_GAMMA_CLIENT", None)
    monkeypatch.setattr(httpx, "Client", FakeClient)

    first = era._global_current_gamma_client(timeout_seconds=6.0)
    second = era._global_current_gamma_client(timeout_seconds=3.0)

    assert first is second
    assert clients == [first]
    assert first.kwargs["base_url"] == "https://gamma-api.polymarket.com"
    assert first.kwargs["limits"].max_connections == 16


