    assert witness.probability_content_identity != (
        recaptured.probability_witness.probability_content_identity
    )
    assert revision_prior_permissions == [
        False,
        False,
        False,
        False,
        True,
        True,
        False,
    ]

    missing_observations = sqlite3.connect(":memory:")
