@pytest.mark.parametrize("execution_mode", ("TAKER_LIMIT", "MAKER_REST"))
def test_global_batch_candidate_block_keeps_sibling_eligible(
    monkeypatch,
    reason,
    blocked_action,
    sibling_action,
    execution_mode,
):
    decision_at = _dt.datetime(2026, 7, 10, 8, 0, tzinfo=_dt.timezone.utc)
    event = _global_scope_event(city="Alpha", source_run_id="run-a")
    scope = current_global_auction_scope_from_events(
        (event,), captured_at_utc=decision_at
    )
    family_key = scope.family_keys[0]
    prepared = SimpleNamespace(
        probability_witness=SimpleNamespace(
            family_key=family_key,
            captured_at_utc=decision_at,
            posterior_identity_hash="run-a",
            witness_identity="q-run-a",
        )
    )
    candidate_a = SimpleNamespace(
        candidate_id="candidate-a",
        action=blocked_action,
        family_key=family_key,
        bin_id="bin-a",
        side="NO",
        token_id="token-a",
        execution_mode=execution_mode,
    )
    family_entry_block = reason.startswith(
        (
            "LIVE_ENTRY_BLOCKED:entry_readiness_family:",
            (
                "EDLI_LIVE_CERTIFICATE_BUILD_FAILED:"
                "LIVE_ENTRY_PROBABILITY_AUTHORITY_UNQUALIFIED:"
            ),
        )
    ) or reason == (
        "LIVE_INFERENCE_INPUTS_MISSING:"
        "GLOBAL_DAY0_FAST_OBSERVATION_ENTRY_STALE"
    )
    candidate_b = SimpleNamespace(
        candidate_id="candidate-b",
        action=("BUY" if family_entry_block else sibling_action),
        family_key=family_key,
        bin_id=("bin-b" if family_entry_block else "bin-a"),
        side=("YES" if family_entry_block else "NO"),
        token_id=("token-b" if family_entry_block else "token-a"),
    )
    candidate_c = SimpleNamespace(
        candidate_id="candidate-c",
        action="SELL",
        family_key=family_key,
        bin_id="bin-a",
        side="NO",
        token_id="token-a",
    )
    winner_candidate = candidate_c if family_entry_block else candidate_b
    selections = iter(
        SimpleNamespace(
            decision=SimpleNamespace(candidate=candidate, no_trade_reason=None),
            winner_event_id=event.event_id,
            actuation=SimpleNamespace(
                decision=SimpleNamespace(candidate=candidate),
                actuation_identity=identity,
                wealth_witness_identity="wealth-1",
            ),
        )
        for candidate, identity in (
            (candidate_a, "actuation-a"),
            (winner_candidate, "actuation-b"),
        )
    )
    base_asset = _global_test_book("book-candidate", price="0.40").assets[0]
    asset = SimpleNamespace(
        **(
            vars(base_asset)
            | {
                "family_key": family_key,
                "bin_id": candidate_a.bin_id,
                "token_id": candidate_a.token_id,
                "side": candidate_a.side,
            }
        )
    )
    sibling_buy_asset = SimpleNamespace(
        **(
            vars(base_asset)
            | {
                "family_key": family_key,
                "bin_id": candidate_b.bin_id,
                "token_id": candidate_b.token_id,
                "side": candidate_b.side,
            }
        )
    )
    book = SimpleNamespace(
        witness_identity="book-candidate",
        captured_at_utc=decision_at,
        max_age=_dt.timedelta(seconds=30),
        assets=((asset, sibling_buy_asset) if family_entry_block else (asset,)),
        sell_assets=(asset,),
    )
    calls = {
        "select": 0,
        "wealth": 0,
        "preflight": [],
        "proof_wrapper": 0,
        "books": 0,
        "venue": 0,
    }
    monkeypatch.setattr(
        global_batch_runtime, "scan_current_global_auction_scope", lambda **_: scope
    )
    monkeypatch.setattr(
        global_batch_runtime,
        "replace",
        lambda value, **changes: SimpleNamespace(**(vars(value) | changes)),
    )

    def wealth(*_, **__):
        calls["wealth"] += 1
        return _WealthNamespace(
            spendable_cash_usd=Decimal("10"),
            witness_identity="wealth-1",
            economic_identity="wealth-economics-1",
            strategy_capital_allocation=_test_strategy_allocation(),
        )

    monkeypatch.setattr(
        global_batch_runtime, "current_portfolio_wealth_witness", wealth
    )

    def select(_prepared, **kwargs):
        policy = kwargs["candidate_policy_rejection_resolver"]
        if calls["select"] == 0:
            assert policy(candidate_a) is None
            assert policy(candidate_b) is None
        else:
            expected_a = (
                f"GLOBAL_PREFLIGHT_CANDIDATE_INELIGIBLE:{reason}"
                if calls["select"] == 1
                else None
            )
            assert policy(candidate_a) == expected_a
            if family_entry_block:
                assert policy(candidate_b) == (
                    f"GLOBAL_PREFLIGHT_CANDIDATE_INELIGIBLE:{reason}"
                )
                assert policy(candidate_c) is None
            else:
                assert policy(candidate_b) is None
            assert kwargs["preflight_excluded_by_family"] == {}
        calls["select"] += 1
        return next(selections)

    monkeypatch.setattr(
        global_batch_runtime, "select_prepared_global_auction", select
    )

    def preflight(_event, actuation, _at, _authority):
        candidate = actuation.decision.candidate
        calls["preflight"].append(candidate.candidate_id)
        if candidate is candidate_a:
            if reason.startswith(
                "GLOBAL_ACTUATION_MARKET_AUTHORITY_SUPERSEDED:"
            ):
                receipt = EventSubmissionReceipt(
                    False,
                    _event.event_id,
                    _event.causal_snapshot_id,
                    reason=reason,
                    proof_accepted=False,
                )
                supersession = era._global_curve_supersession_from_receipt(receipt)
                assert supersession is not None
                status, replacement_candidate, preflight_reason = supersession
                return global_batch_runtime.GlobalWinnerPreflight(
                    status=status,
                    replacement_candidate=replacement_candidate,
                    reason=preflight_reason,
                    rejection_receipt=receipt,
                )
            if reason.startswith("GLOBAL_PREFLIGHT_CANDIDATE_PROOF_INVALID:"):
                proof_failure = reason.partition(":")[2]

                def fail_selected_leg(
                    event_arg,
                    decision_time_arg,
                    *,
                    global_actuation,
                    preflight_only,
                ):
                    calls["proof_wrapper"] += 1
                    assert event_arg is _event
                    assert decision_time_arg == _at
                    assert global_actuation is actuation
                    assert preflight_only is True
                    assert calls["venue"] == 0
                    raise ValueError(proof_failure)

                receipt = era._global_preflight_candidate_receipt(
                    fail_selected_leg,
                    event=_event,
                    actuation=actuation,
                    decision_time=_at,
                )
                assert receipt.submitted is False
                assert receipt.side_effect_status == "NO_SUBMIT"
                assert calls["venue"] == 0
                return global_batch_runtime.GlobalWinnerPreflight(
                    status=era._global_preflight_block_status(receipt.reason),
                    reason=receipt.reason,
                )
            return global_batch_runtime.GlobalWinnerPreflight(
                status=era._global_preflight_block_status(reason),
                reason=reason,
            )
        return global_batch_runtime.GlobalWinnerPreflight(
            status="STABLE",
            binding_token="binding-b",
        )

    def actuate(_event, actuation, _at, token, _authority):
        assert actuation.decision.candidate is winner_candidate
        assert token == "binding-b"
        calls["venue"] += 1
        return EventSubmissionReceipt(
            True,
            event.event_id,
            event.causal_snapshot_id,
            proof_accepted=True,
            side_effect_status="SUBMITTED",
        )

    def next_book(probabilities, _at):
        calls["books"] += 1
        return probabilities, book

    result = global_batch_runtime.process_current_global_batch(
        (event,),
        decision_time=decision_at,
        world_conn=object(),
        forecast_conn=object(),
        trade_conn=object(),
        payload_reader=lambda current: json.loads(current.payload_json),
        prepare_event=lambda current, _at: EventSubmissionReceipt(
            False,
            current.event_id,
            current.causal_snapshot_id,
            prepared_global_family=prepared,
        ),
        actuate_winner=lambda *_: pytest.fail("preflighted lane owns actuation"),
        preflight_winner=preflight,
        actuate_preflighted_winner=global_batch_runtime.GlobalOneShotActuator(
            actuate
        ),
        stamp_receipt=lambda receipt: receipt,
        venue_submit_count=lambda: calls["venue"],
        current_execution=lambda *_: object(),
        current_time_provider=lambda: decision_at,
        current_book_epoch_provider=next_book,
    )

    assert calls == {
        "select": 2,
        "wealth": 1,
        "preflight": ["candidate-a", winner_candidate.candidate_id],
        "proof_wrapper": (
            1
            if reason.startswith("GLOBAL_PREFLIGHT_CANDIDATE_PROOF_INVALID:")
            else 0
        ),
        "books": 1,
        "venue": 1,
    }
    assert result.winner_event_id == event.event_id
    assert result.venue_submit_count == 1
    assert result.receipts[event.event_id].submitted is True


def test_global_batch_initial_unclaimable_fallthrough_keeps_feasible_sell_in_same_cut(
    monkeypatch,
):
    decision_at = _dt.datetime(2026, 7, 10, 8, 0, tzinfo=_dt.timezone.utc)
